import React from 'react';

export default function DashboardHome() {
  return (
    <div style={{ minHeight: '100%', backgroundColor: '#F9FAFB' }}>
      <div style={{ padding: '2rem 2.5rem' }}>
        <h1 style={{ fontSize: 26, fontWeight: 700, color: '#2c313c', margin: 0 }}>Dashboard</h1>
        <p style={{ fontSize: 14, color: '#6B7280', margin: '8px 0 0', maxWidth: 560 }}>
          Welcome to RedFlagAlert. Use the menu to open search, portfolios, analytics with Data Bot,
          and more.
        </p>
      </div>
    </div>
  );
}
